_POOLS = {
    "15-停止.md": _CH15,
    "16-爬回.md": _CH16,
    "17-小的路.md": _CH17,
    "18-漏句.md": _CH18,
    "19-馆藏.md": _CH19,
    "20-静音.md": _CH20,
    "21-随河.md": _CH21,
    "22-空白站.md": _CH22,
    "23-八个早晨.md": _CH23,
}

_VERBS = ["抓袖口", "留空白", "绕开大路", "咽回去", "不补全", "空半拍", "贴栏杆", "数到四停"]


def unique_para(chapter: str, i: int) -> str:
    pool = _POOLS[chapter]
    tpl = pool[i % len(pool)]
    week = i // 7 + 1
    day = ["一", "二", "三", "四", "五", "六", "日"][i % 7]
    base = tpl.format(
        week=week,
        day=day,
        loc=_LOCS[(i * 7 + 3) % len(_LOCS)],
        time=_TIMES[(i * 11 + 5) % len(_TIMES)],
        w=_WEATHER[(i * 13 + 2) % len(_WEATHER)],
        obj=_OBJS[(i * 17 + 1) % len(_OBJS)],
        vb=_VERBS[(i * 19 + 4) % len(_VERBS)],
    )
    # Embed index so repeated templates stay unique paragraphs (not padding-pool dupes).
    tag = f"第{week}周周{day}记{i:02d}"
    if base.endswith("。"):
        return base[:-1] + f"，{tag}不写进报告。"
    return base + f"，{tag}不写进报告。"
